import java.util.*;
import java.io.*;

public class Main {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader scan = new FastReader();
        int n = scan.nextInt();
        String s = scan.next();

        int cur = 0, len = 0, ans = 0, insideWords = 0;

        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            switch (ch) {
                case '(':
                case ')':
                case '_':
                    if (len > 0) {
                        if (cur == 1) insideWords++;
                        else ans = Math.max(ans, len);
                        len = 0;
                    }
                    if (ch == '(') cur = 1;
                    if (ch == ')') cur = 0;
                    break;
                default:
                    len++;
            }
        }

        ans = Math.max(ans, len);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        out.println(ans + " " + insideWords);
        out.close();
    }
}
